import {compactTalentNetwork as talentNetwork,compactRank as talentRank,compactConnected as talentConnected,compactCost,compactText as talentText,compactNextText,buyCompactTalent as buyTalent,refundCompactTalent as refundTalent} from './compact-talents.js';
import {decorateTreeDetail} from './tree-presentation.js';
import {treePresentationPoint} from './tree-layout.js';
import {SKILLS,RANKED_SKILLS,skillRank,skillText,skillUpgradeCost,canLearn,learn,equip,upgradeSkill,canRebuild,movement,power} from './core.js';
import {TALENTS,TALENT_SIZE,TALENT_SECTORS,TALENT_EFFECTS} from './talents.js';
import {progressionEffects,invalidateProgression} from './progression-effects.js';
import {skillPointCost} from './pillars.js';
import {approvedTalentNodeGlyph,approvedTalentSectorGlyph} from './talent-icons-v5.js';
const number=n=>Number(n.toFixed(2)).toLocaleString('pt-BR');

const maxRank=n=>n.kind==='root'?1:n.kind==='skill'?(RANKED_SKILLS.includes(n.id)?3:1):n.max;
export function talentPurchaseState(s,n){
 const rank=talentRank(s,n.id),max=rank>=maxRank(n),skill=n.kind==='skill',active=s.equipped.includes(n.id),editable=canRebuild(s),connected=talentConnected(s,n.id,SKILLS);
 // A disconnected grouped branch has no next purchasable member yet.
 const cost=max||!connected?null:skill?rank?skillUpgradeCost(s,n.id).points:skillPointCost(n):compactCost(s,n.id,SKILLS);
 return {rank,max,skill,active,editable,connected,cost};
}
export class TalentView{
 constructor(){this.selected='ear';this.zoom=.55;this.position=null;}
 markup(s,id){if(id)this.selected=id;const net=talentNetwork(SKILLS),lookup=new Map(net.nodes.map(n=>[n.id,n]));
  return `<section class="web-top"><div><h2>TEIA DE ECOS</h2></div><div class="web-points"><b>✦ ${s.experience.points}</b><span>PONTOS DE TALENTO · NV. ${s.experience.level}</span></div></section><nav class="web-sectors" aria-label="Especializações">${TALENT_SECTORS.map((g,i)=>`<button data-sector="${i}" style="--sector:${g.color}">${approvedTalentSectorGlyph(i)}${g.name}</button>`).join('')}</nav><div class="web-layout" data-compact-talents="true"><div class="web-map-wrap"><div class="web-tools"><button data-zoom="-" aria-label="Diminuir árvore">−</button><b id="webZoom">${Math.round(this.zoom*100)}%</b><button data-zoom="+" aria-label="Ampliar árvore">+</button><button id="webCenter">ORIGEM</button><button id="webExpand" aria-pressed="false">EXPANDIR</button><details class="quiet-details"><summary>CONTROLES</summary><p>Arraste com o botão direito. Dois cliques para comprar. + e − ajustam o zoom.</p></details></div><div class="web-viewport" tabindex="0" aria-label="Mapa de talentos. Arraste ou use as barras de rolagem."><div class="web-size" style="width:${TALENT_SIZE*this.zoom}px;height:${TALENT_SIZE*this.zoom}px"><div class="web-canvas" style="transform:scale(${this.zoom})"><svg class="web-edges" viewBox="0 0 3000 3000" aria-hidden="true">${[880,1170].map(radius=>`<circle cx="1500" cy="1500" r="${radius}"/>`).join('')}${net.overview.map(([a,b])=>{const p=lookup.get(a),q=lookup.get(b);return `<path class="${talentRank(s,a)&&talentRank(s,b)?'lit':''}" style="--edge:${TALENT_SECTORS[q.sector]?.color||TALENT_SECTORS[0].color}" d="M${p.x},${p.y} L${q.x},${q.y}"/>`;}).join('')}</svg>${net.nodes.map(n=>{const rank=talentRank(s,n.id),max=rank>=maxRank(n);return `<button class="web-node ${n.kind} ${rank?'owned':''} ${max?'maxed':''} ${this.selected===n.id?'selected':''} ${talentConnected(s,n.id,SKILLS)?'reachable':''} ${s.equipped.includes(n.id)?'equipped':''}" style="left:${n.x}px;top:${n.y}px;--sector:${TALENT_SECTORS[n.sector].color}" data-talent="${n.id}" title="${n.name} · ${max?'MÁXIMO':rank+'/'+(maxRank(n)===Infinity?'∞':maxRank(n))}" aria-label="${n.name}, ${max?'máximo':rank+' níveis'}" aria-pressed="${this.selected===n.id}">${approvedTalentNodeGlyph(n.members?.[0]||n)}${n.kind==='root'?'<b>ORIGEM</b>':`<small>${max?'✓':n.kind==='mastery'?'∞':rank||''}</small>`}${n.kind==='skill'?`<em>${n.name}</em>`:''}</button>`;}).join('')}</div></div></div><div class="web-map-legend"><span>● BÔNUS</span><span>◆ MARCO</span><span>✦ HABILIDADE</span><span class="max-mark">✓ MÁXIMO</span><span>∞ MAESTRIA</span></div></div><aside class="web-sidebar"><div id="webDetail"></div><details class="web-totals" open><summary>BÔNUS SOMADOS</summary><div id="webTotals"></div></details></aside></div>`;
 }
 bind(root,s,onChange){this.root=root;this.state=s;this.onChange=onChange;const vp=root.querySelector('.web-viewport');
  const center=(x,y)=>{vp.scrollLeft=x*this.zoom-vp.clientWidth/2;vp.scrollTop=y*this.zoom-vp.clientHeight/2;};
  if(this.position){vp.scrollLeft=this.position.x;vp.scrollTop=this.position.y;}else{const initial=talentNetwork(SKILLS).nodes.find(n=>n.id===this.selected);center(initial?.x??1500,initial?.y??1500);}
  root.querySelectorAll('[data-talent]').forEach(b=>b.onclick=()=>{if(this.dragged)return;this.selected=b.dataset.talent;this.detail();});
  root.querySelectorAll('[data-sector]').forEach(b=>b.onclick=()=>{const n=talentNetwork(SKILLS).nodes.find(n=>n.members&&n.sector===Number(b.dataset.sector));const point=n.members?n:treePresentationPoint(n);center(point.x,point.y);this.selected=n.id;this.detail();});
  root.querySelector('#webCenter').onclick=()=>center(1500,1500);
  vp.oncontextmenu=e=>e.preventDefault();
  const expand=root.querySelector('#webExpand'),dialog=root.closest('dialog')||root;expand.setAttribute('aria-pressed',String(dialog.classList.contains('tree-expanded')));expand.onclick=()=>{const on=dialog.classList.toggle('tree-expanded');expand.setAttribute('aria-pressed',String(on));expand.textContent=on?'RECOLHER':'EXPANDIR';};
  root.querySelectorAll('[data-talent]').forEach(b=>b.ondblclick=e=>{e.preventDefault();if(this.dragged)return;this.selected=b.dataset.talent;this.detail();const buy=root.querySelector('#webBuy');if(buy&&!buy.disabled)buy.click();});
  root.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>{const x=(vp.scrollLeft+vp.clientWidth/2)/this.zoom,y=(vp.scrollTop+vp.clientHeight/2)/this.zoom;this.zoom=Math.max(.32,Math.min(1.5,this.zoom+(b.dataset.zoom==='+'?.15:-.15)));root.querySelector('.web-canvas').style.transform=`scale(${this.zoom})`;const size=root.querySelector('.web-size');size.style.width=size.style.height=TALENT_SIZE*this.zoom+'px';root.querySelector('#webZoom').textContent=Math.round(this.zoom*100)+'%';center(x,y);});
  let drag=null;vp.onpointerdown=e=>{if(e.button!==0&&e.button!==2)return;e.preventDefault();this.dragged=false;drag={x:e.clientX,y:e.clientY,sx:vp.scrollLeft,sy:vp.scrollTop};};vp.onpointermove=e=>{if(!drag)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>7){this.dragged=true;vp.setPointerCapture(e.pointerId);}if(this.dragged){vp.scrollLeft=drag.sx-(e.clientX-drag.x);vp.scrollTop=drag.sy-(e.clientY-drag.y);}};vp.onpointerup=vp.onpointercancel=()=>{drag=null;};this.detail();
 }
 detail(){const root=this.root,s=this.state,n=talentNetwork(SKILLS).nodes.find(n=>n.id===this.selected);if(!n)return;
  const net=talentNetwork(SKILLS),lookup=new Map(net.nodes.map(q=>[q.id,q])),edgeSvg=root.querySelector('.web-edges');edgeSvg?.querySelectorAll('.selection-link').forEach(q=>q.remove());
  const primary=new Set(net.overview.map(e=>[...e].sort().join('|')));
  for(const [a,b]of net.edges.filter(e=>e.includes(n.id)&&!primary.has([...e].sort().join('|')))){const p=lookup.get(a),q=lookup.get(b);edgeSvg?.insertAdjacentHTML('beforeend',`<path class="selection-link" style="stroke:#2fbfcd;stroke-dasharray:8 8;opacity:.55" d="M${p.x},${p.y} L${q.x},${q.y}"/>`);}
  root.querySelectorAll('[data-talent]').forEach(b=>{b.classList.toggle('selected',b.dataset.talent===n.id);b.setAttribute('aria-pressed',b.dataset.talent===n.id);});root.querySelectorAll('[data-sector]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.sector)===n.sector)));const {rank,max,skill,active,editable,cost,connected}=talentPurchaseState(s,n);
  const next=n.kind==='root'?'':n.kind==='mastery'?`+${number(.035*Math.log2((rank+2)/(rank+1))*100)}% poder no Abismo.`:skill?skillText(s,n.id,rank+1):n.members?compactNextText(s,n,SKILLS):talentText(n);
  root.querySelector('#webDetail').innerHTML=`<div class="web-selection"><div class="web-detail-icon" style="color:${TALENT_SECTORS[n.sector].color}">${approvedTalentNodeGlyph(n.members?.[0]||n)}</div><span class="web-kicker">${max?'✓ MÁXIMO':n.kind==='mastery'?'∞ MAESTRIA':n.kind==='notable'?'◆ MARCO MAIOR':skill?'✦ HABILIDADE':'● MELHORIAS AGRUPADAS'}</span></div><h3>${n.name}</h3>${n.kind==='root'?'<p>ESCOLHA UM NÓ VIZINHO</p>':`${rank?`<p class="web-current-effect">ATUAL · ${skill?skillText(s,n.id):talentText(n,rank)}</p>`:''}<b class="web-rank">${rank} / ${maxRank(n)===Infinity?'∞':maxRank(n)}</b>${!max?`<div class="web-next"><span>${rank?'PRÓXIMO NÍVEL':'AO APRENDER'}</span><strong>${next||'Conecte um nó vizinho para revelar a próxima melhoria.'}</strong></div>`:''}${!editable?'<b class="web-paused">AJUSTE NO REFÚGIO</b>':`${!max?`<button class="primary" id="webBuy" ${s.experience.points<cost||!connected?'disabled':''}>${connected?(rank?'MELHORAR':'APRENDER')+' · '+cost+' PT':'REQUER UM VIZINHO'}</button>`:''}${skill&&rank&&!n.passive?`<button class="secondary" id="webEquip" ${!active&&s.equipped.length>=5?'disabled':''}>${active?'DESEQUIPAR':'EQUIPAR'}</button>`:''}${skill&&rank&&n.passive?'<b>SEMPRE ATIVA</b>':''}${!skill&&rank&&!s.run?'<button class="secondary" id="webRefund">DEVOLVER 1 NÍVEL</button>':''}`}`}`;
  const effects=progressionEffects(s);root.querySelector('#webTotals').innerHTML=Object.entries(TALENT_EFFECTS).filter(([id])=>effects[id]>0).map(([id,def])=>`<div><span>${def.name}</span><b>+${number(effects[id]*(def.unit==='%'?100:1))}${def.unit}</b></div>`).join('')||'<p>SEM BÔNUS</p>';
  const changed=fn=>{if(!fn())return;invalidateProgression(s);progressionEffects(s);this.position={x:root.querySelector('.web-viewport').scrollLeft,y:root.querySelector('.web-viewport').scrollTop};this.onChange(n.id);};
  const buy=root.querySelector('#webBuy');if(buy)buy.onclick=()=>changed(()=>skill?rank?upgradeSkill(s,n.id):learn(s,n.id):buyTalent(s,n.id,SKILLS));const eq=root.querySelector('#webEquip');if(eq)eq.onclick=()=>changed(()=>equip(s,n.id));const refund=root.querySelector('#webRefund');if(refund)refund.onclick=()=>{if(!refundTalent(s,n.id,SKILLS)){refund.textContent='SUSTENTA OUTROS NÓS';return;}invalidateProgression(s);this.position={x:root.querySelector('.web-viewport').scrollLeft,y:root.querySelector('.web-viewport').scrollTop};this.onChange(n.id);};
  if(root.dataset?.treeEcos==='03'||root.closest?.('[data-tree-ecos="03"]'))decorateTreeDetail(root,s,n);
 }
}
